(* [comment removed for export] *)
Lemma wview_mrd_p : forall m a, wview usegs m a <> None -> exists b, mrd usegs m a = Some b.
Proof.
  intros m a H. unfold mrd. destruct (m a) as [b|] eqn:E; [eauto|].
  unfold wview in H. rewrite E in H. unfold seg_rom, memory_read. change (Z.of_N 1) with 1.
  destruct (find_segment usegs (bv_unsigned a) 1) as [s|] eqn:F; [|congruence].
  assert (Hin : forall l, find_segment l (bv_unsigned a) 1 = Some s -> In s l).
  { induction l as [|x l IH]; cbn; [congruence|]. destruct (_ && _); [left; congruence|right; auto]. }
  assert (Hall : forallb seg_readable usegs = true) by (vm_compute; reflexivity).
  rewrite forallb_forall in Hall. rewrite (Hall s (Hin usegs F)).
  destruct (seg_writable s); [|congruence]. change (N.to_nat 1) with 1%nat. cbn [segment_read_bytes].
  destruct (segment_byte_at (seg_bytes s) (Z.to_N (bv_unsigned a - Z.of_N (seg_base s)))) as [b|]; [eauto|congruence].
Qed.

