(* [comment removed for export] *)
Definition wksp_mach (tl msv : Z) : Z :=
  Z.land ((Z.shiftl (bv_swrap 32 (Z.shiftl 1 (tl mod 32)) mod 18446744073709551616) 2 + Z.shiftl 1 (tl mod 64) +
           Z.shiftr (Z.shiftl ((msv + 1) mod 18446744073709551616) 32 mod 18446744073709551616) 31 + 19)
          mod 18446744073709551616)
         18446744073709551612 + 516.

Lemma wksp_size_mach : forall tl msv, 5 <= tl <= 12 -> 0 <= msv <= 255 ->
